static constexpr unsigned kChangeDelegateRva=0x13B1010;
using PickDone=std::function<void(bool,const std::vector<unsigned>&)>;
struct Row {unsigned id;std::wstring label;};struct List {GameList value;};
struct Dialog {std::array<unsigned char,0x300> memory{},native_list{},native_bar{},native_page{},native_footer{},native_back{},native_clip{},native_confirm{},native_round_back{};std::array<Obj,1> pages{};unsigned char config[0x400]={};Obj object=memory.data();unsigned char column[0x60]={};std::vector<Row> rows;PickDone done;std::function<void(Dialog &,bool)> on_frame;std::function<void(Dialog &)> on_created;std::function<void(unsigned)> command;std::array<std::wstring,3> button_names;bool completed=false;};
struct Command {void **vtable;Dialog *dialog;unsigned index;};static void *command_vtable[6]={};
struct PaneBounds {int x,y,width,height;};
static Dialog *active;static std::vector<std::unique_ptr<Dialog>> retained;static std::vector<unsigned> selection;static std::function<void(bool,int)> number_done;static bool number_open;
static std::unique_ptr<Dialog> choices(const std::wstring &,const std::vector<std::wstring>&names,const std::vector<unsigned>&ids,bool multiple,const std::set<unsigned>&initial,PickDone done){auto r=std::make_unique<Dialog>();*reinterpret_cast<unsigned *>(r->config+0x18)=multiple?2:1;*reinterpret_cast<unsigned *>(r->config+0xA0)=1;*reinterpret_cast<unsigned *>(r->config+0x100)=1;for(size_t i=0;i<ids.size();++i)r->rows.push_back({ids[i],names[i]});r->done=std::move(done);selection.assign(initial.begin(),initial.end());return r;}
static bool open(std::unique_ptr<Dialog> r){check(!active && !number_open,"no dialog reentrancy from native close callback");check(*reinterpret_cast<unsigned *>(r->config+0xA4)==1 && *reinterpret_cast<unsigned *>(r->column+0x10)==1000,"internal viewport configured before original constructor (not a later outer resize)");check(*reinterpret_cast<unsigned *>(r->config+0x9C)==0 && *reinterpret_cast<unsigned *>(r->config+0x114)==1,"CCZ has no redundant tab and constructs no default officer hover popup");Obj list=r->native_list.data(),bar=r->native_bar.data(),cfg=r->config;footer_owner=r->native_footer.data();old_footer_button=r->native_back.data();round_confirm=r->native_confirm.data();round_back=r->native_round_back.data();memcpy(r->object+0x188,&footer_owner,8); r->pages[0]=r->native_page.data();Obj clip=r->native_clip.data();memcpy(r->pages[0]+0xA0,&clip,8);Obj pages=reinterpret_cast<Obj>(r->pages.data());memcpy(list+0x130,&pages,8);unsigned count=1;memcpy(list+0x20C,&count,4);memcpy(r->object+0x180,&list,8);memcpy(r->object+0x198,&bar,8);memcpy(r->object+0x1A8,&cfg,8);if(r->on_created){check(!active,"footer controls created before modal entrance, never from frame");r->on_created(*r);}active=r.get();retained.push_back(std::move(r));return true;}
static void collect(Dialog &d,GameList &out){for(unsigned id:selection)for(auto &row:d.rows)if(row.id==id)out.links.push_back({nullptr,reinterpret_cast<Obj>(&row)});for(size_t i=1;i<out.links.size();++i)out.links[i-1].next=&out.links[i];}
static void close(Dialog &d,bool ok){check(&d==active,"close only own native dialog");active=nullptr;d.completed=true;auto callback=d.done;callback(ok,selection);}
static void release_closed(){check(!active && !number_open,"release only after native resume");retained.clear();}
static void abandon(){active=nullptr;number_open=false;number_done={};retained.clear();}
static bool number(int,int minimum,int maximum,std::function<void(bool,int)> done){check(minimum==0 && maximum==255,"native number input bounds");number_done=std::move(done);number_open=true;return true;}
// No make/dispose helpers: frame-time replacement must fail at compilation.
