static void __fastcall save_unbind(Obj p,unsigned event){check(p==round_confirm+0x70 && event==0x7FFFFFFE,"remove only the root save button generic accept binding");memset(save_callback,0,sizeof(save_callback));}
static void __fastcall save_bind(Obj p,unsigned event,Obj callback){check(p==round_confirm && event==0x7FFFFFFE && pointer(callback,56)==callback,"bind stable shared command functor to persistent round save button");memcpy(save_callback,callback,sizeof(save_callback));}
